/* Live marketplace. Authorization and prices are enforced by database policies/triggers. */
(() => {
  let client, session, profile, epoch=0, recovery=false, authStep='email', authEmail='', authBackground=null, returnRoute='#/', ownerIntent=new URLSearchParams(location.search).get('owner')==='1';
  let authNext='#/dashboard', avatarUrl='',verificationRequest=null,verificationReview=null,verificationStaff=false;
  const safeNext=value=>{const v=String(value||'');return v.length<1500 && (/^#\/(dashboard|bookings|owner|account|favourites|staff)$/.test(v)||/^#\/listing\/[a-zA-Z0-9-]+(?:\?[^#]*)?$/.test(v))?v:'#/dashboard'};
  const loginLink=next=>'#/login?next='+encodeURIComponent(safeNext(next));
  const setupLink=next=>'#/account?next='+encodeURIComponent(safeNext(next));
  const afterLogin=()=>authNext;
  const esc=safe;
  const money=v=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(Number(v));
  const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
  const field=(label,name,type='text',value='',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const namePart=value=>String(value||'').replace(/\s+/g,' ').trim().slice(0,100);
  function identityNames(user){
    const metadata=user?.user_metadata||{};
    let first=namePart(metadata.given_name||metadata.first_name);
    let last=namePart(metadata.family_name||metadata.last_name);
    const full=namePart(metadata.full_name||metadata.name);
    if((!first||!last)&&full&&!full.includes('@')){
      const words=full.split(' ');
      if(words.length>1){first=first||words[0];last=last||words.slice(1).join(' ')}
    }
    return {first,last,full:first&&last?`${first} ${last}`.slice(0,120):''};
  }
  const hasProfileName=p=>!!p?.display_name?.trim()&&p.display_name.trim()!=='Traveller';
  function verificationState(){
    if(!verificationRequest)return 'not_submitted';
    if(!verificationReview || verificationReview.identity_path!==verificationRequest.identity_path ||
      verificationReview.licence_path!==verificationRequest.licence_path ||
      verificationReview.reviewed_birth_date!==verificationRequest.birth_date ||
      verificationReview.reviewed_licence_type!==verificationRequest.licence_type ||
      verificationReview.reviewed_licence_expiry!==verificationRequest.licence_expiry ||
      (profile?.details?.birth_date&&profile.details.birth_date!==verificationRequest.birth_date) ||
      verificationReview.reviewed_name?.trim().toLocaleLowerCase()!==profile?.display_name?.trim().toLocaleLowerCase())return 'pending';
    if(verificationReview.status==='approved'&&verificationRequest.licence_expiry&&verificationRequest.licence_expiry<today())return 'expired';
    return verificationReview.status;
  }
  const verificationLabel=s=>({approved:'Verified',pending:'Pending staff review',rejected:'Needs correction',expired:'Licence expired',not_submitted:'Not verified'}[s]||'Not verified');
  const btn=(text,action,id='')=>`<button type="button" class="btn live-secondary" data-live="${action}" data-id="${esc(id)}">${esc(text)}</button>`;
  const ownerView=()=>parseRoute().path==='/owner'||(parseRoute().path==='/account'&&safeNext(parseRoute().params.get('next'))==='#/owner');
  const nav=()=>`<nav class="live-nav"><a href="#/boats">Explore boats</a><a href="#/bookings">My bookings</a>${session?'<a href="#/account">My profile</a>'+btn('Log out','logout'):'<a href="#/login">Log in</a>'}</nav>`;
  const page=(title,body)=>{
    const {path,params}=parseRoute();
    if(session&&['/dashboard','/bookings','/owner','/account','/favourites','/staff'].includes(path)){
      const links=[['/dashboard','Overview','dashboard'],['/account','My profile','user'],['/bookings','My bookings','calendar'],['/favourites','Saved boats','heart'],...(profile?.account_type==='owner'?[['/owner','My boats','ship'],['/owner?view=requests','Booking requests','mail']]:[]),...(verificationStaff?[['/staff','Staff verification','shield']]:[])];
      const memberName=esc(profile?.display_name||'Traveller');
      const initials=esc((profile?.display_name||'G').slice(0,1).toUpperCase());
      return `<header class="member-header"><a class="member-brand" href="#/">${waveLogo()}<span>Get By Boat</span></a><nav aria-label="Top navigation"><a href="#/boats">Explore boats</a><a href="#/how-it-works">How it works</a><span class="member-locale">EN · EUR</span><a class="member-host-link" href="#/owner">${icon('plus')} List your boat</a><a class="member-mini-avatar" href="#/account" aria-label="My profile">${avatarUrl?`<img src="${esc(avatarUrl)}" alt="">`:initials}</a></nav></header><main class="member-shell"><aside class="member-sidebar"><div class="member-side-label">MY ACCOUNT</div><a href="#/account" class="member-identity">${avatarUrl?`<img class="member-avatar" src="${esc(avatarUrl)}" alt="Your profile photo">`:`<div class="member-avatar member-avatar-empty" aria-hidden="true">${initials}</div>`}<span><strong>${memberName}</strong><small>${profile?.account_type==='owner'?'Boat owner':'Traveller account'}</small></span>${icon('chevron')}</a><nav aria-label="Account navigation">${links.map(([href,label,symbol])=>`<a href="#${href}" ${path===href.split('?')[0]&&(href.includes('?')?params.get('view')==='requests':!params.get('view'))?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span></a>`).join('')}</nav><div class="member-side-bottom"><a href="#/contact">${icon('headset')} Help & support</a><button type="button" data-live="logout">${icon('arrow')} Log out</button></div></aside><section class="member-main">${path==='/dashboard'?'':`<div class="member-page-kicker">YOUR GET BY BOAT ACCOUNT</div><h1>${title}</h1>`}${body}</section></main>`;
    }
    return `${header()}<main class="shell live-page">${nav()}<h1>${title}</h1>${body}</main>${footer()}`;
  };
  const errorText=e=>esc(e?.message||'Something went wrong. Please try again.');
  const status=s=>({pending_owner:'Waiting for owner',awaiting_payment:'Accepted · payment not connected',confirmed:'Confirmed',cancelled:'Cancelled',declined:'Declined'}[s]||s);
  const check=({data,error})=>{if(error)throw error;return data};
  const dateFields=()=>field('First day','start_date','date',state.start||today(),`required min="${today()}"`)+field('Last day','end_date','date',state.end||state.start||today(),`required min="${today()}"`);
  const photo=url=>{try{const u=new URL(url);return u.origin===AUTH_CONFIG.supabaseUrl&&u.pathname.startsWith('/storage/v1/object/public/boat-photos/')?u.href:''}catch{return ''}};
  const picture=b=>photo(b.photo_url)?`<img class="live-photo" src="${esc(photo(b.photo_url))}" alt="${esc(b.name)}" loading="lazy">`:'<div class="live-placeholder">A day at sea awaits</div>';
  const socialButton=(provider,label)=>`<button type="button" class="auth-provider" data-live="social-${provider}"><span aria-hidden="true" class="auth-provider-icon">${provider==='google'?'<svg viewBox="0 0 24 24"><path fill="#4285F4" d="M21.8 12.2c0-.7-.1-1.5-.2-2.2H12v4.2h5.5a4.8 4.8 0 0 1-2.1 3.1v2.6h3.4c2-1.8 3-4.5 3-7.7z"/><path fill="#34A853" d="M12 22c2.8 0 5.2-.9 6.8-2.5l-3.4-2.6c-.9.6-2 .9-3.4.9-2.7 0-5-1.8-5.8-4.2H2.7v2.7A10.3 10.3 0 0 0 12 22z"/><path fill="#FBBC05" d="M6.2 13.6a6 6 0 0 1 0-3.2V7.7H2.7a10 10 0 0 0 0 8.6z"/><path fill="#EA4335" d="M12 6.2c1.5 0 2.8.5 3.8 1.5L18.7 5A9.6 9.6 0 0 0 12 2a10.3 10.3 0 0 0-9.3 5.7l3.5 2.7C7 8 9.3 6.2 12 6.2z"/></svg>':'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M17.1 12.7c0-2 1.6-3 1.7-3.1-1-1.4-2.4-1.6-2.9-1.6-1.2-.1-2.4.7-3 .7-.7 0-1.6-.7-2.7-.7-1.4 0-2.6.8-3.3 2-1.4 2.4-.4 6 1 8 .6 1 1.4 2 2.4 1.9 1-.1 1.3-.7 2.6-.7s1.6.7 2.7.7 1.7-1 2.4-1.9c.7-1.1 1-2.1 1-2.2-.1 0-1.9-.7-1.9-3.1zM15.1 6.7c.6-.8 1-1.8.9-2.9-.9 0-2 .6-2.6 1.3-.6.7-1.1 1.8-1 2.8 1 .1 2-.5 2.7-1.2z"/></svg>'}</span>${label}</button>`;
  const loginPage=()=>`<div class="auth-background" inert aria-hidden="true">${authBackground||home()}</div><div class="auth-scrim" data-auth-backdrop><section class="auth-dialog" role="dialog" aria-modal="true" aria-labelledby="auth-dialog-title" tabindex="-1"><div class="auth-dialog-head"><button type="button" class="auth-close" data-live="auth-close" aria-label="Close login">×</button><span>${recovery?'Reset password':ownerIntent?'Boat owner · Log in or sign up':'Customer · Log in or sign up'}</span></div><div class="auth-dialog-body"><h2 id="auth-dialog-title">${recovery?'Set a new password':ownerIntent?'Welcome aboard, captain':'Welcome to Get By Boat'}</h2>${!recovery?`<p class="auth-owner-copy">${ownerIntent?'List your boat, manage your calendar and respond to booking requests.':authNext.startsWith('#/listing/')?'Log in to continue your booking request. Your boat and dates are saved.':'Find your next day at sea and manage your booking requests.'}</p>`:''}<form data-live-form="auth" class="live-form auth-form">${!recovery?field('Email','email','email',authEmail,'required autocomplete="email" placeholder="Email"'):''}${recovery||authStep==='password'?field('Password','password','password','','required minlength="'+(recovery||authMode==='signup'?'10':'1')+'" autocomplete="'+(recovery||authMode==='signup'?'new-password':'current-password')+'"'):''}<button class="btn auth-primary" type="submit">${recovery?'Save password':authStep==='email'?'Continue':authMode==='signup'?'Create account':'Log in'}</button><p role="status" data-feedback></p>${!recovery?`<div class="live-auth-divider">OR</div><div class="live-social">${socialButton('google','Continue with Google')}${socialButton('apple','Continue with Apple')}</div><div class="auth-switch"><button type="button" data-live="auth-mode">${authMode==='signup'?'Already registered? Log in':'New here? Create account'}</button>${authStep==='password'?'<button type="button" data-live="reset">Forgot password?</button>':''}</div>`:''}</form></div></section></div>`;
  const authRedirect=()=>location.origin+location.pathname+'?auth_callback=1'+loginLink(authNext);
  function closeAuth(){authStep='email';authEmail='';authBackground=null;ownerIntent=false;location.hash=/^#\/(owner|account|bookings|login)(?:\?|$)/.test(returnRoute)?'#/':returnRoute;render();setTimeout(()=>document.querySelector('a[href="#/login"]')?.focus(),0)}
  function focusAuth(){const dialog=document.querySelector('.auth-dialog');document.body?.classList.toggle('auth-open',!!dialog);if(dialog)(dialog.querySelector('input[name="display_name"]')||dialog.querySelector(authStep==='password'?'input[name="password"]':'input'))?.focus();}
  document.addEventListener('keydown',event=>{const dialog=document.querySelector('.auth-dialog');if(!dialog)return;if(event.key==='Escape'){event.preventDefault();closeAuth();return}if(event.key==='Tab'){const items=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),a[href],select,textarea')];const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}});
  document.addEventListener('click',event=>{if(event.target.matches?.('[data-auth-backdrop]'))closeAuth()});
  const profileForm=(next='#/bookings')=>{
    const destination=safeNext(next),owner=destination==='#/owner',type=profile?.account_type==='owner'||owner?'owner':'customer';
    const names=identityNames(session?.user),d=profile?.details||{};
    return `<form data-live-form="profile" data-account-type="${type}" data-next="${esc(destination)}" class="live-card live-form"><h2>${owner&&profile?.account_type!=='owner'?'Set up your owner account':!profile?'Complete your customer profile':'Your details'}</h2><p>${owner?'Confirm your name to manage your boats and guest requests.':'We only need your name to create your customer account.'}</p><div class="live-columns">${field('First name','first_name','text',d.first_name||names.first,'required maxlength="100" autocomplete="given-name"')}${field('Surname','last_name','text',d.last_name||names.last,'required maxlength="100" autocomplete="family-name"')}</div><button class="btn">${owner&&profile?.account_type!=='owner'?'Continue as boat owner':'Continue to my account'}</button><p role="status" data-feedback></p></form>`;
  };
  const profileDialog=(next=authNext)=>{
    const destination=safeNext(next),owner=destination==='#/owner',type=profile?.account_type==='owner'||owner?'owner':'customer';
    // Provider metadata is only a name suggestion, never an authorization claim.
    const names=identityNames(session?.user),d=profile?.details||{};
    const first=d.first_name||names.first,last=d.last_name||names.last;
    return `<div class="auth-background" inert aria-hidden="true">${authBackground||home()}</div><div class="auth-scrim" data-auth-backdrop><section class="auth-dialog" role="dialog" aria-modal="true" aria-labelledby="auth-dialog-title" tabindex="-1"><div class="auth-dialog-head"><button type="button" class="auth-close" data-live="auth-close" aria-label="Close account setup">×</button><span>${owner?'Your owner account':'Finish signing up'}</span></div><div class="auth-dialog-body"><div class="auth-step-label">ONE LAST THING</div><h2 id="auth-dialog-title">${owner?'Welcome aboard, captain':'Welcome aboard!'}</h2><p class="auth-owner-copy">${owner?'Confirm your details to start listing your boat.':'We couldn’t retrieve your full name from your sign-in provider. Enter it once to finish your customer account.'}</p><form data-live-form="profile" data-account-type="${type}" data-next="${esc(destination)}" class="live-form auth-form"><div class="auth-name-fields">${field('First name','first_name','text',first,'required maxlength="100" autocomplete="given-name" placeholder="First name"')}${field('Surname','last_name','text',last,'required maxlength="100" autocomplete="family-name" placeholder="Surname"')}</div><button class="btn auth-primary" type="submit">${owner?'Continue as boat owner':destination.startsWith('#/listing/')?'Continue to my boat':'Go to my dashboard'}</button><p role="status" data-feedback></p><p class="auth-profile-note">Your customer account is already created. You can change your details later in My profile.</p></form></div></section></div>`;
  };
  async function current(){const {data,error}=await client.auth.getUser();if(error&&!error.message?.includes('Auth session missing'))throw error;session=data.user?{user:data.user}:null;profile=session?check(await client.from('profiles').select('*').eq('id',session.user.id).maybeSingle()):null;
    if(session){
      const names=identityNames(session.user);
      if(!profile){
        // Every new OAuth/email identity starts as a customer. Only an explicit owner setup changes this role.
        const details=names.full?{first_name:names.first,last_name:names.last}:{};
        check(await client.from('profiles').upsert({id:session.user.id,display_name:names.full,details,account_type:'customer'},{onConflict:'id',ignoreDuplicates:true}));
        profile=check(await client.from('profiles').select('*').eq('id',session.user.id).maybeSingle());
      }
      if(profile&&names.full){
        // Backfill incomplete records without overwriting names edited by the customer.
        const details=profile.details||{},changes={...details},blank=!hasProfileName(profile);
        if(!details.first_name)changes.first_name=names.first;
        if(!details.last_name)changes.last_name=names.last;
        if(blank||!details.first_name||!details.last_name){
          const value={details:changes};if(blank)value.display_name=names.full;
          profile=check(await client.from('profiles').update(value).eq('id',session.user.id).select().single());
        }
      }
    }
    verificationRequest=null;verificationReview=null;verificationStaff=false;
    if(session){
      verificationStaff=!!check(await client.rpc('is_verification_staff'));
      verificationRequest=check(await client.from('verification_requests').select('*').eq('user_id',session.user.id).maybeSingle());
      verificationReview=check(await client.from('verification_reviews').select('*').eq('user_id',session.user.id).maybeSingle());
    }
    avatarUrl='';if(profile?.avatar_path){const result=await client.storage.from('profile-photos').createSignedUrl(profile.avatar_path,3600);if(!result.error)avatarUrl=result.data.signedUrl;}
  }
  const requireAccount=()=>!session?loginPage():!hasProfileName(profile)?profileDialog(authNext):null;
  function verificationForm(){
    const v=verificationRequest||{},s=verificationState();
    return `<div class="profile-panel verification-intro"><div class="verification-heading"><div><span class="member-page-kicker">IDENTITY & BOATING SAFETY</span><h2>Verify your identity and boat licence</h2><p>Complete verification before sending a boat booking request. You can create and use your account without uploading anything.</p></div><span class="verification-badge ${esc(s)}">${esc(verificationLabel(s))}</span></div><div class="verification-steps"><span>${icon('user')} Your legal name</span><span>${icon('shield')} ID / passport</span><span>${icon('ship')} Boat licence</span><span>${icon('check')} Staff review</span></div>${s==='rejected'&&verificationReview?.note?`<p class="verification-warning">Reviewer note: ${esc(verificationReview.note)}</p>`:''}${s==='approved'?'<p class="verification-good">Your identity and boating licence have been approved. You can request a booking while your licence remains valid. Uploading replacement documents starts a new review.</p>':''}${s==='pending'?'<p class="member-note">Your documents have been submitted. A Get By Boat staff member will review the information. Bookings remain blocked until approval.</p>':''}</div>
    <form class="profile-panel live-form verification-upload" data-live-form="verification" enctype="multipart/form-data"><h2>${v.user_id?'Update verification documents':'Submit documents for verification'}</h2><p class="member-note">The name on your ID/passport and boat licence must match your customer profile: <strong>${esc(profile.display_name)}</strong>. If it does not, correct your profile before uploading.</p><div class="live-columns"><label>Identity document type<select name="identity_type" required><option value="id_card" ${v.identity_type==='id_card'?'selected':''}>National ID card</option><option value="passport" ${v.identity_type==='passport'?'selected':''}>Passport</option></select></label>${field('Date of birth (as shown on ID)','birth_date','date',v.birth_date||profile.details?.birth_date||'',`required max="${today()}"`)}</div><div class="live-columns"><label>ID card / passport image or PDF<input type="file" name="identity_file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label><label>Boat driving licence image or PDF<input type="file" name="licence_file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label></div><div class="live-columns"><label>Boat licence category<select name="licence_type" required>${[['coastal','Coastal'],['offshore','Offshore'],['inland','Inland'],['professional','Professional skipper'],['other','Other recognised licence']].map(([value,label])=>`<option value="${value}" ${v.licence_type===value?'selected':''}>${label}</option>`).join('')}</select></label>${field('Licence expiration (leave blank if permanent)','licence_expiry','date',v.licence_expiry||'')}</div><label class="live-check"><input type="checkbox" name="documents_own" required> I confirm both documents are mine, accurate and provided for Get By Boat staff to verify my identity and qualification.</label><p class="member-note">Accepted: JPEG, PNG, WebP or PDF, up to 5 MB each. Private documents are not shared with boat owners. Reviewers should delete copies after review. <a href="#/privacy">Privacy information</a> · <a href="mailto:pere.juran@gmail.com?subject=Verification%20document%20deletion">Request document deletion</a></p><button class="btn" type="submit">${s==='approved'?'Submit replacement documents':'Submit for manual review'}</button><p role="status" data-feedback></p></form>`;
  }
  function accountProfile(tab){
    const d=profile.details||{};
    const select=(label,name,options)=>`<label>${label}<select name="${name}"><option value="">Select…</option>${options.map(x=>`<option ${d[name]===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
    const tabs=`<nav class="member-tabs" aria-label="Profile sections">${[['verification','Verifications'],['information','Information'],['experience','Boating experience'],['password','Password']].map(([id,label])=>`<a href="#/account?tab=${id}" ${tab===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
    if(tab==='verification')return tabs+verificationForm();
    if(tab==='password')return tabs+`<form class="profile-panel live-form" data-live-form="password"><h2>Change your password</h2>${field('New password','password','password','','required minlength="10" autocomplete="new-password"')}${field('Re-enter new password','confirm','password','','required minlength="10" autocomplete="new-password"')}<button class="btn">Save password</button><p data-feedback role="status"></p></form><div class="profile-panel"><h2>Account support</h2><p>To request deletion of your account and personal data, contact our team from your registered email address.</p><a href="mailto:pere.juran@gmail.com?subject=Account%20deletion%20request">Request account deletion</a></div>`;
    if(tab==='experience')return tabs+`<form class="profile-panel live-form" data-live-form="details" data-section="experience"><h2>Your time on the water</h2><div class="live-columns">${select('Your level','boating_level',['Beginner','Some experience','Experienced','Professional skipper'])}${select('You prefer','boat_preference',['Motorboat','RIB','Sailboat','Catamaran','Yacht','Jetski'])}</div><fieldset><legend>Your boat licences</legend>${['Coastal licence','Offshore licence','Inland licence','Radio operator certificate','Professional skipper licence'].map(x=>`<label class="live-check"><input type="checkbox" name="licences" value="${x}" ${(d.licences||[]).includes(x)?'checked':''}>${x}</label>`).join('')}</fieldset><label>About you and your boating experience<textarea name="bio" rows="6" maxlength="3000" placeholder="Tell owners about your boating experience and favourite days at sea.">${esc(d.bio||'')}</textarea></label><p class="member-note">These details are self-reported. An owner may ask to see your licence before a rental.</p><button class="btn">Save experience</button><p data-feedback role="status"></p></form>`;
    return tabs+`<form class="profile-panel live-form" data-live-form="avatar"><h2>Your profile photo</h2><div class="profile-photo-preview">${avatarUrl?`<img src="${esc(avatarUrl)}" alt="Your profile photo">`:'<span aria-hidden="true">◎</span>'}</div><label>Select an image<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><small>JPEG, PNG or WebP. Maximum 5 MB. Your photo is stored privately.</small><button class="btn">Save photo</button><p data-feedback role="status"></p></form><form class="profile-panel live-form" data-live-form="details" data-section="information"><h2>Personal information</h2><p class="member-note">Your name is filled from Google when available, or from the details you supplied during sign-up. You can edit it here.</p><div class="live-columns">${field('First name','first_name','text',d.first_name||'','required maxlength="100" autocomplete="given-name"')}${field('Surname','last_name','text',d.last_name||'','required maxlength="100" autocomplete="family-name"')}${field('Email','email','email',session.user.email||'','readonly')}${select('Gender (optional)','gender',['Female','Male','Other','Prefer not to say'])}${field('Date of birth (optional)','birth_date','date',d.birth_date||'',`max="${today()}"`)}${field('Languages spoken','languages','text',d.languages||'','maxlength="150"')}${field('Telephone','phone','tel',d.phone||'','maxlength="40" autocomplete="tel"')}${field('Address','address','text',d.address||'','maxlength="200" autocomplete="street-address"')}${field('Postal code','postal_code','text',d.postal_code||'','maxlength="30" autocomplete="postal-code"')}${field('City','city','text',d.city||'','maxlength="100" autocomplete="address-level2"')}</div><p class="member-note">Your personal details are private to your account. Contact details are optional.</p><button class="btn">Save details</button><p data-feedback role="status"></p></form>`;
  }
  function boatForm(b={}) {return `<form data-live-form="boat" data-id="${esc(b.id||'')}" class="live-card live-form"><h2>${b.id?'Edit your boat':'List your boat'}</h2>${field('Boat name','name','text',b.name||'','required maxlength="120"')}<div class="live-columns">${field('Country','country','text',b.country||'','required maxlength="80"')}${field('Marina / location','location','text',b.location||'','required maxlength="160"')}</div><label>Boat type<select name="type">${['Motorboat','RIB','Sailboat','Catamaran','Yacht','Jetski'].map(t=>`<option ${t===b.type?'selected':''}>${t}</option>`).join('')}</select></label><div class="live-columns">${field('Daily price (€)','price','number',b.price||'','required min="1" max="100000" step="0.01"')}${field('Maximum guests','guests','number',b.guests||1,'required min="1" max="100"')}${field('Cabins','cabins','number',b.cabins||0,'required min="0"')}</div><label>Tell guests about your boat<textarea name="description" maxlength="10000" rows="5">${esc(b.description||'')}</textarea></label><label>Boat photograph (JPEG, PNG or WebP, max 5 MB)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><label class="live-check"><input type="checkbox" name="published" ${b.published?'checked':''}> Publish this listing</label><p>A rental day runs from 09:00 to 19:00. Every booking needs your acceptance.</p><button class="btn">Save boat</button><p data-feedback role="status"></p></form>`}
  function requests(rows,owner=false){return rows.length?rows.map(r=>`<article class="live-card"><span class="live-status">${esc(status(r.status))}</span><h3>${esc(r.boats?.name||'Boat reservation')}</h3><p>${esc(r.start_date)} — ${esc(r.end_date)} · 09:00–19:00 each day · ${r.guests} guests</p>${owner?`<p>Guest: ${esc(r.customer_name)}</p>`:''}<p>Charter ${money(r.charter_price)} + service fee ${money(r.service_fee)} = <strong>${money(r.total)}</strong></p><small>Request ${esc(r.id)}</small><div class="live-actions">${owner&&r.status==='pending_owner'?btn('Accept request','accept',r.id)+btn('Decline','decline',r.id):''}${!owner&&['pending_owner','awaiting_payment'].includes(r.status)?btn('Cancel request','cancel',r.id):''}</div>${r.status==='awaiting_payment'?'<p>Your dates are held. Online payment is not available yet. This is not a paid, confirmed booking.</p>':''}</article>`).join(''):'<div class="live-card"><p>No booking requests yet.</p></div>'}
  function dashboardHome(rows,boats){
    const name=esc((profile.display_name||'Traveller').split(' ')[0]);
    const pending=rows.filter(r=>r.status==='pending_owner'||r.status==='awaiting_payment').length;
    const profileSteps=[!!avatarUrl,!!profile.details?.boating_level,verificationState()==='approved'].filter(Boolean).length;
    const bookingCards=rows.length?rows.slice(0,2).map(r=>`<a class="member-booking-preview" href="#/bookings"><div class="member-booking-icon">${icon('ship')}</div><div><strong>${esc(r.boats?.name||'Boat rental')}</strong><span>${esc(r.start_date)} – ${esc(r.end_date)} · ${esc(r.guests)} guests</span></div><span class="member-status">${esc(status(r.status))}</span>${icon('arrow')}</a>`).join(''):`<div class="member-card-empty"><span class="member-empty-symbol">${icon('ship')}</span><h3>No trips booked yet</h3><p>Your next unforgettable day on the water is waiting.</p><a class="member-inline-link" href="#/boats">Explore boats ${icon('arrow')}</a></div>`;
    return `<div class="member-dashboard"><div class="member-hero"><div class="member-hero-copy"><span class="member-eyebrow">YOUR PERSONAL SPACE · GET BY BOAT</span><h1>Welcome aboard,<br><em>${name}.</em></h1><p>Everything you need for your next day at sea, all in one place.</p><a class="btn member-hero-btn" href="#/boats">Explore boats ${icon('arrow')}</a></div><div class="member-hero-image" aria-hidden="true"></div></div>
      <div class="member-stats"><a href="#/bookings" class="member-stat"><span>${icon('calendar')} Total requests</span><strong>${rows.length}</strong><small>View your booking history ${icon('arrow')}</small></a><a href="#/bookings" class="member-stat"><span>${icon('clock')} Awaiting updates</span><strong>${pending}</strong><small>Check request status ${icon('arrow')}</small></a><a href="#/account?tab=verification" class="member-stat"><span>${icon('shield')} Profile essentials</span><strong>${profileSteps}<small> / 3</small></strong><small>Verify your account ${icon('arrow')}</small></a></div>
      <div class="member-dashboard-columns"><section class="member-panel"><div class="member-panel-head"><div><span class="member-eyebrow">YOUR JOURNEYS</span><h2>Booking requests</h2></div><a href="#/bookings">View all ${icon('arrow')}</a></div>${bookingCards}</section>
      <aside class="member-panel member-profile-panel"><div class="member-panel-head"><div><span class="member-eyebrow">A LITTLE ABOUT YOU</span><h2>Your profile</h2></div></div><p class="member-panel-intro">A complete profile makes every booking easier.</p><div class="member-profile-task"><span class="${avatarUrl?'done':''}">${avatarUrl?icon('check'):icon('user')}</span><div><strong>Profile photo</strong><small>${avatarUrl?'Added to your account':'Let owners recognise you'}</small></div><a href="#/account?tab=information">${avatarUrl?'Edit':'Add'}</a></div><div class="member-profile-task"><span class="${profile.details?.boating_level?'done':''}">${profile.details?.boating_level?icon('check'):icon('ship')}</span><div><strong>Boating experience</strong><small>${profile.details?.boating_level?'Information saved':'Share your experience on water'}</small></div><a href="#/account?tab=experience">${profile.details?.boating_level?'Edit':'Add'}</a></div><div class="member-profile-task"><span class="${verificationState()==='approved'?'done':''}">${verificationState()==='approved'?icon('check'):icon('shield')}</span><div><strong>ID & boat licence</strong><small>${esc(verificationLabel(verificationState()))}</small></div><a href="#/account?tab=verification">${verificationState()==='approved'?'View':'Verify'}</a></div><a class="member-outline-action" href="#/account?tab=verification">Go to verification ${icon('arrow')}</a></aside></div>
      <div class="member-bottom-promo"><div><span class="member-eyebrow">SHARE THE SEA</span><h2>${profile.account_type==='owner'?'Manage your boats':'Have a boat to share?'}</h2><p>${profile.account_type==='owner'?`You have ${boats.length} ${boats.length===1?'boat listing':'boat listings'}. Manage your availability and requests.`:'List your boat on Get By Boat and welcome guests aboard.'}</p></div><a href="#/owner${profile.account_type==='owner'?'':'?edit=new'}" class="member-outline-action">${profile.account_type==='owner'?'My boats':'List your boat'} ${icon('arrow')}</a></div></div>`;
  }
  async function staffPage(){
    if(!verificationStaff)return page('Staff verification','<div class="profile-panel"><h2>Access restricted</h2><p>Only authorised Get By Boat reviewers can access customer documents.</p></div>');
    const rows=check(await client.from('verification_requests').select('*').order('submitted_at',{ascending:false}).limit(50));
    if(!rows.length)return page('Staff verification','<div class="profile-panel"><h2>No verification requests yet</h2><p>New customer ID and boat licence submissions will appear here.</p></div>');
    const reviews=check(await client.from('verification_reviews').select('*').in('user_id',rows.map(r=>r.user_id)));
    const profiles=check(await client.from('profiles').select('id,display_name,details').in('id',rows.map(r=>r.user_id)));
    const cards=await Promise.all(rows.map(async r=>{
      const p=profiles.find(x=>x.id===r.user_id),review=reviews.find(x=>x.user_id===r.user_id);
      const current=review?.identity_path===r.identity_path && review?.licence_path===r.licence_path && review?.reviewed_birth_date===r.birth_date && review?.reviewed_licence_type===r.licence_type && review?.reviewed_licence_expiry===r.licence_expiry && review?.reviewed_name?.trim().toLocaleLowerCase()===p?.display_name?.trim().toLocaleLowerCase();
      const status=current?review.status:'pending';
      const [idFile,licenceFile]=current&&['approved','rejected'].includes(status)?[null,null]:await Promise.all([client.storage.from('verification-documents').createSignedUrl(r.identity_path,300),client.storage.from('verification-documents').createSignedUrl(r.licence_path,300)]);
      const documentLink=(result,label)=>!result?`<span class="member-note">${esc(label)}: reviewed; copy scheduled for removal</span>`:result.error?`<span class="member-note">${esc(label)} unavailable (may have been deleted after review)</span>`:`<a class="member-outline-action" target="_blank" rel="noopener noreferrer" href="${esc(result.data.signedUrl)}">View ${esc(label)} · 5-minute link ${icon('arrow')}</a>`;
      return `<article class="profile-panel verification-staff-card"><div class="verification-heading"><div><h2>${esc(p?.display_name||'Customer')}</h2><p>Submitted ${esc(r.submitted_at?.slice(0,10)||'')} · DOB ${esc(r.birth_date)}</p></div><span class="verification-badge ${esc(status)}">${esc(verificationLabel(status))}</span></div><p><strong>Identity:</strong> ${r.identity_type==='passport'?'Passport':'National ID'} · <strong>Licence:</strong> ${esc(r.licence_type)} · <strong>Expiry:</strong> ${esc(r.licence_expiry||'Permanent / not specified')}</p>${p?.details?.birth_date?`<p>Customer profile date of birth: ${esc(p.details.birth_date)}</p>`:''}<div class="verification-document-links">${documentLink(idFile,'ID / passport')}${documentLink(licenceFile,'boat driving licence')}</div>${current&&review?.note?`<p>Previous decision note: ${esc(review.note)}</p>`:''}<form class="live-form verification-review-form" data-live-form="review" data-id="${esc(r.user_id)}"><label>Decision<select name="status" required><option value="approved">Approve documents</option><option value="rejected">Reject / request correction</option></select></label><label class="live-check"><input type="checkbox" name="identity_matches"> I checked that the ID/passport is genuine-looking and matches the customer's legal name and date of birth.</label><label class="live-check"><input type="checkbox" name="licence_matches"> I checked the licence holder matches the ID/passport, and the licence category and validity are suitable.</label><label>Message to customer (required if rejected)<textarea name="note" rows="2" maxlength="1000" placeholder="Explain which details need correction."></textarea></label><button class="btn" type="submit">Save review decision</button><p role="status" data-feedback></p></form></article>`;
    }));
    return page('Staff verification',`<p>Restricted reviewer area. Review both documents carefully before approving. Approved customers may book boats; only verification status is visible outside this area.</p><div class="verification-staff-list">${cards.join('')}</div>`);
  }
  async function route(){const {path,params}=parseRoute();if(!['/boats','/owner','/bookings','/account','/login','/dashboard','/favourites','/staff'].includes(path)&&!path.startsWith('/listing/'))return null;
    if(!client)return ['/login','/owner','/bookings','/account','/dashboard','/favourites','/staff'].includes(path)?loginPage():page('Welcome aboard.','<p>Connecting your account…</p>');
    if(path==='/login'&&session&&!recovery){location.hash=afterLogin();return !profile?profileDialog(authNext):page('Welcome back.','<p>Opening your account…</p>')}
    if(path==='/login')return loginPage();
    if(path==='/owner'&&!session)return loginPage();
    if(path==='/boats') {const boats=check(await client.from('boats').select('*').eq('published',true).order('created_at',{ascending:false}));const search=(params.get('location')||params.get('country')||'').toLowerCase(),type=params.get('type')||'';const filtered=boats.filter(b=>(!search||`${b.location} ${b.country}`.toLowerCase().includes(search))&&(!type||b.type===type));return page('Discover your next <i>adventure.</i>',`<form data-live-form="search" class="live-card live-search">${field('Where would you like to go?','location','search',search)}<label>Boat type<select name="type"><option value="">Any boat</option>${['Motorboat','RIB','Sailboat','Catamaran','Yacht','Jetski'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn">Search</button></form><p>${filtered.length} ${filtered.length===1?'boat':'boats'} · All bookings upon request</p><div class="live-grid">${filtered.map(b=>`<a class="live-card live-boat" href="#/listing/${b.id}">${picture(b)}<h2>${esc(b.name)}</h2><p>${esc(b.location)}, ${esc(b.country)} · ${esc(b.type)} · ${b.guests} guests</p><strong>${money(b.price)} / day</strong></a>`).join('')||'<div class="live-card"><h2>Our next chapter is coming.</h2><p>No published boats match this search yet. Boat owners can add their listings from the owner space.</p><a href="#/owner" class="btn">List your boat</a></div>'}</div>`)}
    if(path.startsWith('/listing/')) {for(const [key,name] of [['start','start'],['end','end']]){const value=params.get(key);if(/^\d{4}-\d{2}-\d{2}$/.test(value||''))state[name]=value;}const selectedGuests=Math.max(1,Math.min(100,Number(params.get('guests'))||1));const b=check(await client.from('boats').select('*').eq('id',path.slice(9)).single());let unavailable=[];if(session)unavailable=check(await client.rpc('boat_availability',{p_boat:b.id}));const licenceNeeded=session&&verificationState()!=='approved';return page(esc(b.name),`<div class="live-columns"><section>${picture(b)}${session?btn('Save to favourites','favourite',b.id):''}<h2>${esc(b.location)}, ${esc(b.country)}</h2><p>${esc(b.type)} · ${b.guests} guests · ${b.cabins} cabins</p><p class="live-description">${esc(b.description)}</p></section><section><form data-live-form="request" data-id="${b.id}" data-price="${b.price}" class="live-card live-form"><h2>${money(b.price)} / day</h2><p>09:00–19:00 each rental day. Owner acceptance required.</p>${dateFields()}${field('Guests','guests','number',selectedGuests,`required min="1" max="${b.guests}"`)}<div data-quote aria-live="polite"></div>${licenceNeeded?`<div class="verification-booking-block"><strong>${icon('shield')} Licence verification required</strong><p>${esc(verificationLabel(verificationState()))}. Submit your ID/passport and boat driving licence, then wait for staff approval before booking.</p><a href="#/account?tab=verification">Go to verification ${icon('arrow')}</a></div>`:''}<button class="btn" ${b.owner_id===session?.user.id||licenceNeeded?'disabled':''}>${licenceNeeded?'Verification required':session?'Send booking request':'Log in to request'}</button><p data-feedback role="status"></p><small>No payment is taken. Your request does not hold the dates until the owner accepts.</small></form><div class="live-card"><h3>Unavailable dates</h3>${session?unavailable.map(d=>`<p>${esc(d.start_date)} — ${esc(d.end_date)}</p>`).join('')||'<p>No dates currently blocked.</p>':'<p>Log in to check availability.</p>'}</div></section></div>`)}
    const guard=requireAccount();if(guard)return guard;
    if(path==='/account')return page('Complete your profile',accountProfile(params.get('tab')||'information'));
    if(path==='/staff')return staffPage();
    if(path==='/dashboard'){
      const rows=check(await client.from('bookings').select('*,boats(name)').eq('customer_id',session.user.id).order('created_at',{ascending:false}));
      const boats=profile.account_type==='owner'?check(await client.from('boats').select('*').eq('owner_id',session.user.id).order('created_at',{ascending:false})):[];
      return page('Dashboard',dashboardHome(rows,boats));
    }
    if(path==='/favourites'){
      const saved=check(await client.from('favourites').select('boat_id,boats(*)').eq('user_id',session.user.id));
      return page('Your favourites',saved.length?`<div class="live-grid">${saved.map(x=>`<article class="live-card">${x.boats?`${picture(x.boats)}<h2>${esc(x.boats.name)}</h2><a href="#/listing/${x.boat_id}">View boat</a>`:'<p>This boat is no longer available.</p>'}${btn('Remove','unfavourite',x.boat_id)}</article>`).join('')}</div>`:'<div class="member-empty"><p>Save the boats you love and find them here.</p><a href="#/boats">Explore boats →</a></div>');
    }
    if(path==='/bookings')return page('My bookings.',`<p>All your booking requests in one place. ${btn('Refresh','refresh')}</p>${requests(check(await client.from('bookings').select('*,boats(name)').eq('customer_id',session.user.id).order('created_at',{ascending:false})))}`);
    if(profile.account_type!=='owner')return profileDialog('#/owner');
    const boats=check(await client.from('boats').select('*').eq('owner_id',session.user.id).order('created_at',{ascending:false}));
    const editing=params.get('edit');if(editing)return page('Your boat. Your next guests.',boatForm(boats.find(b=>b.id===editing)||{}));
    const rows=boats.length?check(await client.from('bookings').select('*,boats(name)').in('boat_id',boats.map(b=>b.id)).order('created_at',{ascending:false})):[];
    if(params.get('view')==='requests')return page('Booking requests.',`<p>Accept or decline requests for your boats. ${btn('Refresh','refresh')}</p>${requests(rows,true)}`);
    const blocks=boats.length?check(await client.from('boat_blocks').select('*').in('boat_id',boats.map(b=>b.id)).order('start_date')):[];
    return page('Welcome back, captain.',`<div class="live-actions"><a class="btn" href="#/owner?edit=new">List a new boat</a>${btn('Refresh','refresh')}</div><h2>Your fleet</h2><div class="live-grid">${boats.map(b=>`<article class="live-card">${picture(b)}<h3>${esc(b.name)}</h3><p>${b.published?'Published':'Draft'} · ${money(b.price)} / day</p><a href="#/owner?edit=${b.id}">Edit listing</a> · <a href="#/listing/${b.id}">View boat</a><details><summary>Manage availability</summary><form data-live-form="block" data-id="${b.id}" class="live-form">${dateFields()}<button class="btn">Block dates</button><p data-feedback role="status"></p></form>${blocks.filter(x=>x.boat_id===b.id).map(x=>`<p>${x.start_date} — ${x.end_date} ${btn('Unblock','unblock',x.id)}</p>`).join('')}</details></article>`).join('')||'<p>Your fleet starts with your first listing.</p>'}</div><div class="live-card"><h2>Your guest requests</h2><p>${rows.filter(r=>r.status==='pending_owner').length} requests waiting for your reply.</p><a class="btn" href="#/owner?view=requests">View booking requests</a></div>`);
  }
  const routes=p=>['/boats','/owner','/bookings','/account','/login','/dashboard','/favourites','/staff'].includes(p)||p.startsWith('/listing/');
  window.liveRender=()=>{
    const {path,params}=parseRoute();const token=++epoch;
    if(path==='/login'){authNext=safeNext(params.get('next')||(params.get('owner')==='1'||new URLSearchParams(location.search).get('owner')==='1'?'#/owner':'#/dashboard'))}
    else if(path==='/owner')authNext='#/owner';
    else if(path==='/staff')authNext='#/staff';
    else if(path==='/account')authNext=safeNext(params.get('next'));
    else if(path==='/bookings')authNext='#/bookings';
    ownerIntent=authNext==='#/owner';
    window.GBB_ACCOUNT_LINK=session?(ownerView()?'#/owner':'#/dashboard'):null;
    const showProfile=!!session&&!recovery&&path==='/owner'&&profile?.account_type!=='owner';
    const showAuth=showProfile||path==='/login'||(!session&&['/owner','/bookings','/account','/dashboard','/favourites','/staff'].includes(path));
    if(showAuth){if(!authBackground)authBackground=returnRoute==='#/'?home():app.innerHTML||home()}
    else{returnRoute=location.hash||'#/';authBackground=null;document.body?.classList.remove('auth-open')}
    if(!routes(path))return false;
    // Keep the same dialog while Auth initializes; do not flash a second login design.
    app.innerHTML=showProfile?profileDialog(authNext):showAuth?loginPage():page('Get By Boat','<p role="status">Loading…</p>');focusAuth();
    route().then(html=>{if(token!==epoch)return;app.innerHTML=html;quote();focusAuth()}).catch(e=>{if(token===epoch)app.innerHTML=page('We couldn’t load this page.',`<p role="alert">${errorText(e)}</p>${btn('Try again','refresh')}`)});return true;
  };
  function quote(){const form=document.querySelector('[data-live-form="request"]');if(!form)return;const d=new FormData(form),n=rentalDayCount(d.get('start_date'),d.get('end_date'));const out=form.querySelector('[data-quote]');if(!n||n<1){out.textContent='Choose a valid rental period.';return}const charter=n*Number(form.dataset.price),fee=serviceFee(charter);out.innerHTML=`<p>${n} ${n===1?'day':'days'} × ${money(form.dataset.price)}: ${money(charter)}</p><p>Service fee: ${money(fee)}</p><p><strong>Total: ${money(charter+fee)}</strong></p>`;}
  const verificationFileTypes={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','application/pdf':'pdf'};
  function safeVerificationFile(file){if(!file?.size||file.size>5242880||!verificationFileTypes[file.type])throw Error('Both documents must be JPEG, PNG, WebP or PDF files under 5 MB each.');}
  document.addEventListener('input',e=>{if(e.target.closest('[data-live-form="request"]'))quote()});
  document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.liveForm)return;e.preventDefault();const button=f.querySelector('button[type="submit"],button:not([type])');if(button?.disabled)return;if(button)button.disabled=true;const feedback=f.querySelector('[data-feedback]');if(feedback)feedback.textContent='Saving…';try{if(!client)throw Error('Connecting your account. Please try again in a moment.');const d=new FormData(f),kind=f.dataset.liveForm;
    if(kind==='search'){location.hash='#/boats?location='+encodeURIComponent(d.get('location'))+'&type='+encodeURIComponent(d.get('type'));return}
    if(kind==='auth'&&!recovery&&authStep==='email'){authEmail=String(d.get('email')||'').trim();authStep='password';render();return}
    if(kind==='auth'){const email=String(d.get('email')||'').trim(),password=String(d.get('password'));if(recovery){check(await client.auth.updateUser({password}));recovery=false;toast('Password updated.');}else if(authMode==='signup'){const result=check(await client.auth.signUp({email,password,options:{emailRedirectTo:authRedirect()}}));if(!result.session){feedback.textContent='Check your inbox to confirm your email. If no email arrives, contact pere.juran@gmail.com.';return}}else check(await client.auth.signInWithPassword({email,password}));await current();location.hash=afterLogin();authStep='email';authEmail='';render();return}
    if(!session){
      if(kind==='request'){
        const start=String(d.get('start_date')||''),end=String(d.get('end_date')||'');
        if(!rentalDayCount(start,end))throw Error('Choose a valid rental period.');
        const query=new URLSearchParams({start,end,guests:String(d.get('guests')||1)});
        authNext=safeNext('#/listing/'+f.dataset.id+'?'+query.toString());
      }
      location.hash=loginLink(authNext);return
    }
    if(kind==='details'){
      const details={...(profile.details||{})}, keys=f.dataset.section==='experience'?['boating_level','boat_preference','bio']:['first_name','last_name','gender','birth_date','languages','phone','address','postal_code','city'];
      for(const key of keys)details[key]=String(d.get(key)||'').trim();
      if(f.dataset.section==='experience')details.licences=d.getAll('licences');
      const value={details};if(f.dataset.section==='information'){
        const first=namePart(d.get('first_name')),last=namePart(d.get('last_name'));
        if(!first||!last)throw Error('Please enter your first name and surname.');
        value.display_name=`${first} ${last}`.slice(0,120);
      }
      check(await client.from('profiles').update(value).eq('id',session.user.id).select().single());await current();feedback.textContent='Your profile has been saved.';return;
    }
    if(kind==='verification'){
      if(!hasProfileName(profile))throw Error('Complete your first name and surname before verification.');
      if(!d.get('documents_own'))throw Error('Confirm the documents belong to you.');
      const identityFile=d.get('identity_file'),licenceFile=d.get('licence_file');
      safeVerificationFile(identityFile);safeVerificationFile(licenceFile);
      const identityType=String(d.get('identity_type')||''),licenceType=String(d.get('licence_type')||'');
      const birthDate=String(d.get('birth_date')||''),licenceExpiry=String(d.get('licence_expiry')||'');
      if(!['id_card','passport'].includes(identityType)||!['coastal','offshore','inland','professional','other'].includes(licenceType))throw Error('Choose valid document types.');
      if(!/^\d{4}-\d{2}-\d{2}$/.test(birthDate)||birthDate>=today())throw Error('Enter your date of birth as shown on your ID.');
      if(licenceExpiry&&(!/^\d{4}-\d{2}-\d{2}$/.test(licenceExpiry)||licenceExpiry<today()))throw Error('Your boat licence must be valid.');
      const uploaded=[],old=verificationRequest;
      try{
        const upload=async(folder,file)=>{
          const key=`${session.user.id}/${folder}/${crypto.randomUUID()}.${verificationFileTypes[file.type]}`;
          check(await client.storage.from('verification-documents').upload(key,file,{contentType:file.type,upsert:false}));
          uploaded.push(key);return key;
        };
        const identityPath=await upload('identity',identityFile),licencePath=await upload('licence',licenceFile);
        check(await client.from('verification_requests').upsert({user_id:session.user.id,identity_type:identityType,identity_path:identityPath,licence_path:licencePath,licence_type:licenceType,licence_expiry:licenceExpiry||null,birth_date:birthDate,submitted_at:new Date().toISOString()},{onConflict:'user_id'}).select().single());
      }catch(error){if(uploaded.length)await client.storage.from('verification-documents').remove(uploaded);throw error;}
      if(old){const obsolete=[old.identity_path,old.licence_path].filter(Boolean);if(obsolete.length)await client.storage.from('verification-documents').remove(obsolete);}
      await current();render();toast('Your documents are securely submitted. Staff approval is required before booking.');return;
    }
    if(kind==='review'){
      if(!verificationStaff)throw Error('Staff review access required.');
      const decision=String(d.get('status')||''),note=String(d.get('note')||'').trim();
      if(!['approved','rejected'].includes(decision))throw Error('Choose an approval or rejection.');
      if(decision==='approved'&&(!d.get('identity_matches')||!d.get('licence_matches')))throw Error('Confirm that you checked both documents and matching identity details.');
      if(decision==='rejected'&&!note)throw Error('Explain to the customer what must be corrected.');
      check(await client.from('verification_reviews').upsert({user_id:f.dataset.id,status:decision,note},{onConflict:'user_id'}).select().single());
      const docs=check(await client.from('verification_requests').select('identity_path,licence_path').eq('user_id',f.dataset.id).single());
      const cleanup=await client.storage.from('verification-documents').remove([docs.identity_path,docs.licence_path]);
      await current();render();toast(cleanup.error?'Decision saved. Document cleanup needs staff attention.':'Decision saved. Document copies removed from private storage.');return;
    }
    if(kind==='avatar'){
      const file=d.get('photo');if(!file?.size||file.size>5242880||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPEG, PNG or WebP under 5 MB.');
      const key=`${session.user.id}/${crypto.randomUUID()}.${{'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type]}`,old=profile.avatar_path;
      check(await client.storage.from('profile-photos').upload(key,file,{contentType:file.type,upsert:false}));
      try{check(await client.from('profiles').update({avatar_path:key}).eq('id',session.user.id).select().single());}catch(error){await client.storage.from('profile-photos').remove([key]);throw error;}
      if(old)await client.storage.from('profile-photos').remove([old]);await current();render();return;
    }
    if(kind==='password'){const password=String(d.get('password')||'');if(password.length<10)throw Error('Use at least 10 characters.');if(password!==d.get('confirm'))throw Error('The passwords do not match.');check(await client.auth.updateUser({password}));f.reset();feedback.textContent='Password updated.';return;}
    if(kind==='profile'){
      const first=namePart(d.get('first_name')),last=namePart(d.get('last_name'));
      if(!first||!last)throw Error('Please enter your first name and surname.');
      const display_name=`${first} ${last}`.slice(0,120);
      check(await client.from('profiles').upsert({id:session.user.id,display_name,details:{...(profile?.details||{}),first_name:first,last_name:last},account_type:profile?.account_type==='owner'?'owner':f.dataset.accountType==='owner'?'owner':'customer'}));
      await current();location.hash=safeNext(f.dataset.next);render();return;
    }
    if(kind==='boat'){let imageUrl;const file=d.get('photo');if(file?.size){if(file.size>5242880||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPEG, PNG or WebP under 5 MB.');const key=`${session.user.id}/${crypto.randomUUID()}.${{'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type]}`;check(await client.storage.from('boat-photos').upload(key,file,{contentType:file.type,upsert:false}));imageUrl=client.storage.from('boat-photos').getPublicUrl(key).data.publicUrl;}const value={owner_id:session.user.id,name:String(d.get('name')).trim(),country:String(d.get('country')).trim(),location:String(d.get('location')).trim(),type:d.get('type'),price:Number(d.get('price')),guests:Number(d.get('guests')),cabins:Number(d.get('cabins')),description:d.get('description'),published:d.get('published')==='on',...(imageUrl?{photo_url:imageUrl}:{})};check(await(f.dataset.id?client.from('boats').update(value).eq('id',f.dataset.id).select().single():client.from('boats').insert(value).select().single()));location.hash='#/owner';render();return}
    if(kind==='request'){if(!hasProfileName(profile)){const query=new URLSearchParams({start:String(d.get('start_date')||''),end:String(d.get('end_date')||''),guests:String(d.get('guests')||1)});location.hash=setupLink('#/listing/'+f.dataset.id+'?'+query.toString());return}if(verificationState()!=='approved'){location.hash='#/account?tab=verification';render();toast('ID and boat driving licence verification is required before booking.');return}const start=d.get('start_date'),end=d.get('end_date');if(end<start)throw Error('Last day must be on or after the first day.');if(verificationRequest?.licence_expiry&&end>verificationRequest.licence_expiry)throw Error('Your boat licence must remain valid through the last rental day.');check(await client.from('bookings').insert({boat_id:f.dataset.id,customer_id:session.user.id,customer_name:profile.display_name,start_date:start,end_date:end,guests:Number(d.get('guests'))}).select().single());toast('Request sent to the owner.');location.hash='#/bookings';return}
    if(kind==='block'){if(d.get('end_date')<d.get('start_date'))throw Error('Last day must be on or after the first day.');check(await client.from('boat_blocks').insert({boat_id:f.dataset.id,start_date:d.get('start_date'),end_date:d.get('end_date')}));render();}
  }catch(err){if(feedback)feedback.textContent=err.message||'Please try again.';else toast(err.message)}finally{if(button)button.disabled=false}},true);
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-live]');if(!b)return;e.preventDefault();if(b.disabled)return;b.disabled=true;try{switch(b.dataset.live){case 'favourite':check(await client.from('favourites').upsert({user_id:session.user.id,boat_id:b.dataset.id},{onConflict:'user_id,boat_id',ignoreDuplicates:true}));toast('Saved to favourites.');break;case 'unfavourite':check(await client.from('favourites').delete().eq('user_id',session.user.id).eq('boat_id',b.dataset.id));render();break;case 'auth-close':closeAuth();break;case 'social-google':case 'social-apple':{
      const provider=b.dataset.live==='social-google'?'google':'apple';
      const feedback=document.querySelector('[data-feedback]');
      if(feedback)feedback.textContent='Connecting…';
      try {
        const response=await fetch(AUTH_CONFIG.supabaseUrl+'/auth/v1/settings',{headers:{apikey:AUTH_CONFIG.supabasePublishableKey}});
        if(!response.ok)throw Error('Unable to check sign-in availability. Please try again.');
        const settings=await response.json();
        if(!settings.external?.[provider])throw Error((provider==='google'?'Google':'Apple')+' sign-in is awaiting activation. Please use email for now.');
        check(await client.auth.signInWithOAuth({provider,options:{redirectTo:authRedirect()}}));
      } catch(error) {if(feedback)feedback.textContent=error.message||'Sign-in could not start. Please try again.';else throw error;}
      break;
    }case 'refresh':await current();render();break;case 'auth-mode':authEmail=document.querySelector('[name="email"]')?.value||authEmail;authMode=authMode==='login'?'signup':'login';render();break;case 'logout':check(await client.auth.signOut());session=null;profile=null;authStep='email';authEmail='';authNext='#/bookings';ownerIntent=false;window.GBB_ACCOUNT_LINK=null;location.hash='#/login';render();break;case 'reset':{const email=document.querySelector('[name="email"]')?.value;if(!email)throw Error('Enter your email address first.');check(await client.auth.resetPasswordForEmail(email,{redirectTo:authRedirect()}));toast('Check your email for the password reset link.');break}case 'accept':case 'decline':case 'cancel':check(await client.from('bookings').update({status:{accept:'awaiting_payment',decline:'declined',cancel:'cancelled'}[b.dataset.live]}).eq('id',b.dataset.id).select().single());render();break;case 'unblock':check(await client.from('boat_blocks').delete().eq('id',b.dataset.id).select().single());render();break}}catch(err){toast(err.message||'Please try again.')}finally{b.disabled=false}});
  // Static sample boats cannot create real requests or paid confirmations.
  document.addEventListener('submit',e=>{if(['reserve-form','checkout-form'].includes(e.target.id)){e.preventDefault();e.stopImmediatePropagation();modal('Example boat','This is an example listing. Explore the live boat catalogue to send a real booking request.');}},true);
  async function boot(){try{client=await authClient();client.auth.onAuthStateChange((event,s)=>{session=s;if(event==='PASSWORD_RECOVERY'){recovery=true;setTimeout(()=>{location.hash='#/login';render()},0)}if(event==='SIGNED_OUT'){profile=null;setTimeout(()=>render(),0)}});await current();if(new URLSearchParams(location.search).has('auth_callback')){const p=parseRoute().params;authNext=safeNext(p.get('next')||(ownerIntent?'#/owner':'#/dashboard'));history.replaceState(null,'',location.pathname+loginLink(authNext));}render()}catch(e){app.innerHTML=page('Connection unavailable.',`<p>${errorText(e)}</p><button class="btn" onclick="location.reload()">Retry</button>`)}}
  render();
  boot();
})();
